-- Generated by scripts/generate-codex-turns-schema.mjs.
-- Read-only activation check: bind hour-aligned UTC verifyFrom/verifyTo. Raw spans in
-- [verifyFrom - 1h, verifyTo + 24h) must be backfilled and retained. One row per turn: any
-- differs = 1 blocks CODEX_TURNS_READ_FROM; clipped = 1 rows are counted, not compared.
SELECT throwIf({verifyTo:DateTime('UTC')} <= {verifyFrom:DateTime('UTC')}
  OR toStartOfHour({verifyFrom:DateTime('UTC')}) != {verifyFrom:DateTime('UTC')} OR toStartOfHour({verifyTo:DateTime('UTC')}) != {verifyTo:DateTime('UTC')},
  'Codex turns verification requires a positive hour-aligned UTC window');

SELECT turn_id, differs, clipped
FROM (
  SELECT TurnId AS turn_id,
    ifNull(t.present, 0) = 1 AS t_present, ifNull(r.present, 0) = 1 AS r_present,
    toUInt8(r_present AND r.end_ts >= {verifyTo:DateTime('UTC')} + INTERVAL 23 HOUR) AS clipped,
    toUInt8(NOT (t_present AND r_present) OR (NOT clipped AND (length(t.conversations) > 1
      OR t.conversations != r.conversations
      OR t.start_ts != r.start_ts
      OR t.end_ts != r.end_ts
      OR t.sampling != r.sampling
      OR t.legacy != r.legacy
      OR t.sampling_models != r.sampling_models
      OR t.legacy_models != r.legacy_models
      OR t.tries != r.tries
      OR t.compactions != r.compactions
      OR t.spawns != r.spawns
      OR t.names_turn != r.names_turn
      OR t.version != r.version))) AS differs
  FROM (
    SELECT UserIdentity, TurnId, toUInt8(1) AS present,
      arraySort(groupUniqArrayMerge(Conversations)) AS conversations,
      min(StartTs) AS start_ts, max(EndTs) AS end_ts,
      uniqExactMerge(SamplingSpans) AS sampling, uniqExactMerge(LegacySpans) AS legacy,
      arraySort(groupUniqArrayMerge(SamplingModels)) AS sampling_models,
      arraySort(groupUniqArrayMerge(LegacyModels)) AS legacy_models,
      uniqExactMerge(SamplingTries) AS tries, uniqExactMerge(Compactions) AS compactions,
      uniqExactMerge(SpawnCalls) AS spawns, max(NamesTurnOnTools) AS names_turn,
      max(AppVersion) AS version
    FROM claude_code.codex_turns_v1
    WHERE TurnHour >= {verifyFrom:DateTime('UTC')} - INTERVAL 1 HOUR AND TurnHour < {verifyTo:DateTime('UTC')} + INTERVAL 24 HOUR
    GROUP BY UserIdentity, TurnId
    HAVING min(TurnHour) >= {verifyFrom:DateTime('UTC')} AND min(TurnHour) < {verifyTo:DateTime('UTC')}
  ) AS t
  FULL OUTER JOIN (
    SELECT UserIdentity, TurnId, toUInt8(1) AS present,
      arraySort(groupUniqArrayIf(turn_conversation, turn_conversation != '')) AS conversations,
      min(span_start) AS start_ts, max(span_end) AS end_ts,
      uniqExactIf(span_key, SpanName = 'codex.sampling') AS sampling,
      uniqExactIf(span_key, SpanName = 'run_sampling_request') AS legacy,
      arraySort(groupUniqArrayIf(span_model, SpanName = 'codex.sampling' AND span_model != '')) AS sampling_models,
      arraySort(groupUniqArrayIf(span_model, SpanName = 'run_sampling_request' AND span_model != '')) AS legacy_models,
      uniqExactIf(span_key, SpanName = 'try_run_sampling_request') AS tries,
      uniqExactIf(span_key, SpanName = 'codex.compaction') AS compactions,
      uniqExactIf(span_key, SpanName IN ('collaborationspawn_agent', 'collaborationfollowup_task', 'multi_agent_v1spawn_agent')) AS spawns,
      max(span_names_turn) AS names_turn,
      maxIf(span_version, span_version != '') AS version
    FROM (
    SELECT if(match(turn_id_raw, '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-7[0-9a-fA-F]{3}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'),
      toStartOfHour(toDateTime(intDiv(reinterpretAsUInt64(reverse(unhex(concat(substring(turn_id_raw, 1, 8), substring(turn_id_raw, 10, 4))))), 1000), 'UTC')),
      toStartOfHour(toDateTime(Timestamp, 'UTC'))) AS TurnHour,
    coalesce(nullIf(ResourceAttributes['user.email'], ''), nullIf(ResourceAttributes['enduser.id'], ''), '') AS UserIdentity,
    coalesce(nullIf(SpanAttributes['turn_id'], ''), SpanAttributes['turn.id']) AS turn_id_raw,
    turn_id_raw AS TurnId,
    SpanAttributes['conversation.id'] AS turn_conversation,
    Timestamp AS span_start,
    toDateTime64(fromUnixTimestamp64Milli(toUnixTimestamp64Milli(Timestamp) + intDiv(Duration, 1000000), 'UTC'), 9) AS span_end,
    SpanName,
    cityHash64(TraceId, SpanId) AS span_key,
    coalesce(nullIf(SpanAttributes['model'], ''), SpanAttributes['gen_ai.request.model']) AS span_model,
    ResourceAttributes['service.version'] AS span_version,
    toUInt8(length(extractGroups(span_version, '^(\\d+)\\.(\\d+)')) = 2
      AND (toFloat64OrZero(extractGroups(span_version, '^(\\d+)\\.(\\d+)')[1]) > 0 OR toFloat64OrZero(extractGroups(span_version, '^(\\d+)\\.(\\d+)')[2]) >= 166)) AS span_names_turn
  FROM claude_code.otel_traces
  WHERE ResourceAttributes['client'] = 'codex'
    AND (SpanAttributes['turn_id'] != '' OR SpanAttributes['turn.id'] != '')
    AND (Timestamp >= {verifyFrom:DateTime('UTC')} - INTERVAL 1 HOUR AND Timestamp < {verifyTo:DateTime('UTC')} + INTERVAL 24 HOUR)
    )
    WHERE TurnId != ''
    GROUP BY UserIdentity, TurnId
    HAVING min(TurnHour) >= {verifyFrom:DateTime('UTC')} AND min(TurnHour) < {verifyTo:DateTime('UTC')}
  ) AS r USING (UserIdentity, TurnId)
)
ORDER BY differs DESC, clipped DESC, turn_id;
